        $this->validateAllRegularWithLunchOutInWithOt = $all || in_array('regular_with_lunch_out_in_with_ot', $testCaseGroup);

        $this->regularFlexibleNoLunchOutIn = (clone $companyShift)->where('code', '003-DAYSHIFT-FLEX-2DOFF-NL0/I')->first();
        $this->validateAllRegularFlexibleNoLunchOutIn = $all || in_array('regular_flexible_no_lunch_out_in', $testCaseGroup);
        $this->regularFlexibleWithLunchOutIn = (clone $companyShift)->where('code', '004-DAYSHIFT-FLEX-2DOFF-WL0/I')->first();
        $this->validateAllRegularFlexibleWithLunchOutIn = $all || in_array('regular_flexible_with_lunch_out_in', $testCaseGroup);

        $this->nightMidnightStartNoLunchOutIn = (clone $companyShift)->where('code', '005-GRAVEYARD-NHT-MIDNIGHT-2DOFF-NL0/I')->first();
        $this->validateAllNightMidnightStartNoLunchOutIn = $all || in_array('night_midnight_start_no_lunch_out_in', $testCaseGroup);
        $this->nightMidnightStartWithLunchOutIn = (clone $companyShift)->where('code', '006-GRAVEYARD-NHT-MIDNIGHT-2DOFF-WL0/I')->first();
        $this->validateAllNightMidnightStartWithLunchOutIn = $all || in_array('night_midnight_start_with_lunch_out_in', $testCaseGroup);

        $this->nightNoLunchOutIn = (clone $companyShift)->where('code', '007-GRAVEYARD-NHT-2DOFF-NL0/I')->first();
        $this->validateAllNightNoLunchOutIn = $all || in_array('night_no_lunch_out_in', $testCaseGroup);

        $this->nightNoLunchOutInWithOt = (clone $companyShift)->where('code', '007-GRAVEYARD-NHT-2DOFF-NL0/I-3MOT')->first();
        $this->validateAllNightNoLunchOutInWithOt = $all || in_array('night_no_lunch_out_in_with_ot', $testCaseGroup);
        $this->nightNoLunchOutInWithOtQuadrupleSplit = (clone $companyShift)->where('code', '007-GRAVEYARD-NHT-2DOFF-NL0/I-10MOTQUADSPLIT')->first();
        $this->validateAllNightNoLunchOutInWithOtQuadrupleSplit = $all || in_array('night_no_lunch_out_in_with_ot_quadruple_split', $testCaseGroup);

        $this->nightWithLunchOutIn = (clone $companyShift)->where('code', '008-GRAVEYARD-NHT-2DOFF-WL0/I')->first();
        $this->validateAllNightWithLunchOutIn = $all || in_array('night_with_lunch_out_in', $testCaseGroup);
        $this->nightWithLunchOutInWithOt = (clone $companyShift)->where('code', '008-GRAVEYARD-NHT-2DOFF-WL0/I-3MOT')->first();
        $this->validateAllNightWithLunchOutInWithOt = $all || in_array('night_with_lunch_out_in_with_ot', $testCaseGroup);
        $this->nightWithLunchOutInWithOtQuadrupleSplit = (clone $companyShift)->where('code', '007-GRAVEYARD-NHT-2DOFF-WL0/I-10MOTQUADSPLIT')->first();
        $this->validateAllNightWithLunchOutInWithOtQuadrupleSplit = $all || in_array('night_with_lunch_out_in_with_ot_quadruple_split', $testCaseGroup);

        $this->nightLunchDoubleSplitNoLunchOutIn = (clone $companyShift)->where('code', '009-GRAVEYARD-NHT-2DOFF-NL0/I-LUNCH-2-SPLIT')->first();
        $this->validateAllNightLunchDoubleSplitNoLunchOutIn = $all || in_array('night_lunch_double_split_no_lunch_out_in', $testCaseGroup);

        $this->nightLunchDoubleSplitWithLunchOutIn = (clone $companyShift)->where('code', '010-GRAVEYARD-NHT-2DOFF-WL0/I-LUNCH-2-SPLIT')->first();
        $this->validateAllNightLunchDoubleSplitWithLunchOutIn = $all || in_array('night_lunch_double_split_with_lunch_out_in', $testCaseGroup);

        $this->nightLunchTripleSplitNoLunchOutIn = (clone $companyShift)->where('code', '011-GRAVEYARD-NHT-2DOFF-NL0/I-LUNCH-3-SPLIT')->first();
        $this->validateAllNightLunchTripleSplitNoLunchOutIn = $all || in_array('night_lunch_triple_split_no_lunch_out_in', $testCaseGroup);

        $this->nightLunchTripleSplitWithLunchOutIn = (clone $companyShift)->where('code', '012-GRAVEYARD-NHT-2DOFF-WL0/I-LUNCH-3-SPLIT')->first();
        $this->validateAllNightLunchTripleSplitWithLunchOutIn = $all || in_array('night_lunch_triple_split_with_lunch_out_in', $testCaseGroup);
