    public function run($debug = false): string
    {
        $attendanceSplitter = app(AttendanceSplitterInterface::class, [$this->company]);
        $attendanceRepository = app(AttendanceRepository::class);

        $passed = 0;
        $failed = 0;

        foreach ($this->testCases() as $attendance){

            if(!$attendance['validate']){continue;}

            $attendanceHydration = $attendanceRepository->hydrateItem($attendance);

            if($attendanceSplitter->generate($attendanceHydration, true, $debug)){
                $passed += 1;
            } else {
                $failed += 1;
            }
        }

        return sprintf('%d/%d', $passed, $passed + $failed);
    }
